// Manual entry point: I curl this with a single lead OR a list of leads.
// Body shapes accepted:
//   { business_name, business_url, business_sector, ... }
//   { leads: [ {...}, {...} ] }
const input = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
if (headers['x-webhook-secret'] !== $vars.WEBHOOK_SECRET) {
  throw new Error('Unauthorized');
}

const raw = Array.isArray(input.leads) ? input.leads : [input];
const leads = raw.filter(l => l && l.business_name && l.business_url && l.business_sector);
if (!leads.length) throw new Error('No valid leads — required fields: business_name, business_url, business_sector');

return leads.map(l => ({ json: { ...l, source: l.source || 'manual' } }));

// Collect all created/updated lead ids.
const items = $input.all();
const ids = [];
for (const it of items) {
  const rows = Array.isArray(it.json) ? it.json : [it.json];
  for (const r of rows) {
    if (r && r.id) ids.push(r.id);
  }
}
return [{ json: { count: ids.length, lead_ids: ids } }];
